import { describe, expect, it } from '@jest/globals';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { naRecordRefusal, parseJson, verifyKeyHistory } from '../src/index.js';
import type { NAKeyHistory } from '../src/index.js';
import { conformanceReceipt } from './receipts.js';

/**
 * The `vouching` conformance suite (Genesis Mesh 1.8.0), generated by the
 * Python reference (genesismesh/conformance/generate_vectors.py vouching) and
 * copied unchanged: records of a succeeded NA key (attestations, treaties,
 * revocation feeds and grants) judged at their own time and judged now, inside
 * the grace, past the horizon, backdated into the old key's window, after the
 * hand-over, by the new key, with a shorter or clamped grace, tampered, and
 * grants that start more than 24 hours after their issue. Every vector runs.
 */
interface Vector {
  id: string;
  kind: string;
  model: string;
  description: string;
  input: {
    genesis: unknown;
    successions: unknown[];
    root_public_key: string;
    record: Record<string, unknown>;
    now: string;
    grace_seconds?: number;
  };
  expected: { at_record_time: string | null; now: string | null };
}

const raw = readFileSync(fileURLToPath(new URL('./fixtures/conformance/vouching.json', import.meta.url)), 'utf-8');
const suite = parseJson(raw) as { suite: string; version: string; vectors: Vector[] };

function history(input: Vector['input']): NAKeyHistory {
  const result = verifyKeyHistory(input.genesis, input.successions, input.root_public_key);
  if (result.history === null) throw new Error(JSON.stringify(result.failures));
  return input.grace_seconds === undefined ? result.history : result.history.withVouchingGrace(input.grace_seconds);
}

describe('vouching conformance suite', () => {
  const receipt = conformanceReceipt('vouching', 'vouching-conformance', 'tests/vouching-conformance.test.ts:vouching conformance suite');

  it('is the reference suite', () => {
    expect(suite.suite).toBe('vouching');
    expect(suite.vectors.length).toBeGreaterThanOrEqual(32);
    expect(new Set(suite.vectors.map(v => v.kind))).toEqual(new Set(['record_vouching']));
  });

  for (const vector of suite.vectors) {
    it(`${vector.id}: ${vector.description}`, () => {
      const h = history(vector.input);
      expect({
        at_record_time: naRecordRefusal(vector.model, vector.input.record, h),
        now: naRecordRefusal(vector.model, vector.input.record, h, { now: vector.input.now }),
      }).toEqual(vector.expected);
      receipt.ran(vector);
    });
  }
});
